function showModal(html) { $('modal').innerHTML = html; $('modalBg').classList.add('show'); }
function hideModal() { $('modalBg').classList.remove('show'); }
const HELP = `<h2>NI&amp;I at Mattoon, IL (test yard)</h2>
<p><b>Your job:</b> the waybill at the top tells you where the car goes. Pick it up with the GP9 and set it where it belongs. Then uncouple and the job pays.</p>
<ul>
<li><b>The picture:</b> your engine and its track are up front. Drag to look around, pinch (or the mouse wheel) to zoom, &#9673; brings you back to the engine. <b>Map</b> shows the whole yard.</li>
<li><b>Switches:</b> tap a switch stand beside the track to throw it; the small letter above it names the switch. Green = straight (normal), red = diverging (reversed) target. If it flashes red, cars or the engine are on the points. You can also tap the markers on the Map.</li>
<li><b>Drive mode:</b> set the reverser to F or R, release the brake, and notch the throttle up. F runs short hood first.</li>
<li><b>Tap mode:</b> tap the track (or a car) in the picture or on the Map and the engine goes there at yard speed. Tapping a car couples to it. The engine lines the switches itself (you'll see the stands flip) and makes any reversing move it needs, pulling the whole cut clear of the switch first. If a car is in the way it tells you which one. In Drive mode you throw every switch yourself.</li>
<li><b>Yard limits and speed:</b> the white YARD LIMIT boards stand at each end of town (Mattoon and Neoga, same rule). Once the rear of your move passes one, your train must have a caboose in it, anywhere in the train (1970s rule). The front can go past freely, so you can shove or run around partway. A light engine (engines only, no cars) is exempt and can run past the boards. Break the rule and you're stopped and fined $100 and 5 rep. Track speed is 25 mph on the main and 10 mph on every other track.</li>
<li><b>Blue flags:</b> when you've spotted cars at a customer and left, they put a blue flag on their track and work the cars behind it. It's usually down by their next switch window (CIC: Mon / Wed / Fri; the others daily), but now and then they leave it up: tap the building and Request removal (5-10 min). Running past a blue flag costs $250 and 20 rep.</li>
<li><b>Waybills:</b> every car has a waybill. Tap a car's tag (or any car in Drive mode) to read it; the menu's Waybills list shows where every car is going and which are ready for IC.</li>
<li><b>Coupling:</b> ease into a car under 4 mph. Faster costs you money and reputation.</li>
<li><b>Uncoupling:</b> stop, then tap the &#9986; between two cars in the picture.</li>
<li><b>TAGS:</b> the TAGS button (top right of the picture) puts a destination tag over every car. The colour is the subdivision (Mattoon is red); the code says where the car goes: HOUSE = freight house door, YARD 1&ndash;6 = that yard track, IC-INT = going to the Illinois Central (leave it on IC Outbound; an IC car becomes IC-INT once it's finished at its HOUSE or YARD spot), HOLD = no orders yet, leave it in the yard. The second line is what's in the car and how many tons (e.g. Paper 43T), or EMPTY.</li>
<li><b>IC interchange:</b> two long stub tracks (about 14 cars each) off the main toward Effingham, running north from the south end right up to the yard ladder (switch IC on the main, then switch IO). On the Map, tap the IC chip at the right edge (or drag) to see them. The Illinois Central leaves cars for us on <b>IC Inbound</b>; cars tagged <b>IC-INT</b> go on <b>IC Outbound</b>. Back in from the main (the switch faces south); tap a car or the track and auto-routing lines the switches and makes the reversing move for you.</li>
<li><b>End day:</b> End Day in the menu (&#9776;) ends the day. Hired crews you marked up on the call sheet do their work then (you won't see them switch). IC picks up every car on IC Outbound and pays per car (see the money summary for the rates), sets out new cars on IC Inbound (if that track is clear), and it's 6:00 AM the next day. Cars anywhere else stay put unless a hired crew moved them.</li>
<li><b>Restart:</b> &#8634; in the top bar puts everything back exactly how the game starts, so you can replay the same situation.</li>
<li><b>Fuel and sand:</b> the engine burns fuel, more at higher notches. Sand stops wheel slip and helps you stop. Refill on the engine track at the fuel pad (costs money). If you run dry, the engine quits.</li>
</ul>
<div class="btns"><button data-act="close">Let's go</button></div>`;
function menu() {
  const T = state.tasks || []; showModal(`<h2>Menu</h2><div class="btns"><button data-act="townsPick">Look at another town</button></div><div class="btns"><button data-nm="fs" data-fs class="alt">${NII.fullscreen.label()}</button><button data-nm="ind" class="alt">Industries</button></div><p>Today's jobs: ${T.filter(t => t.done).length} of ${T.length} done. ${weekday(dayNo())} · Day ${dayNo()}.</p>
  <div class="btns"><button data-act="help" class="alt">How to play</button><button data-act="close">Back to game</button></div>
  <div class="btns"><button data-act="callSheet">Call a crew</button></div>
  <div class="btns"><button data-act="endDayAsk">&#9790; End Day ${dayNo()}</button></div>
  <div class="btns"><button data-act="spotsToggle" class="${spotsOn ? 'red' : 'alt'}">Spot marks: ${spotsOn ? 'ON' : 'OFF'}</button><button data-act="tasks" class="alt">Today's jobs</button></div>
  <div class="btns"><button data-act="namesToggle" class="${namesOn ? 'red' : 'alt'}">Track names: ${namesOn ? 'ON' : 'OFF'}</button><button data-act="waybills" class="alt">Waybills</button></div>
  <div class="btns">${Object.keys(BF).map(K => `<button data-act="bfOpen" data-k="${K}" class="alt">${bfS()[K].up ? '&#9873; ' : ''}${BF[K].short}</button>`).join('')}</div>
  <div class="btns"><button data-act="resetAsk" class="red">&#8634; Restart from the beginning</button></div>`);
}
document.addEventListener('click', e => {
  const b = e.target.closest('[data-act]'); if (!b) return; const a = b.dataset.act;
  if (a === 'close') { hideModal(); state.help = false; save(); }
  else if (a === 'help') showModal(HELP);
  else if (a === 'townsPick') { hideModal(); NII.pickTown(); }
  else if (a === 'nextJob') { hideModal(); }
  else if (a === 'tasks') showTasks();
  else if (a === 'travelGo') departTo(b.dataset.to);
  else if (a === 'spotsToggle') { setSpots(!spotsOn); sfx('tick'); menu(); }
  else if (a === 'namesToggle') { setNames(!namesOn); sfx('tick'); menu(); drawMap(); drawScene(0); }
  else if (a === 'selTask') { state.sel = b.dataset.id; syncTasks(); hideModal(); save(); }
  else if (a === 'resetAsk') askRestart();
  else if (a === 'reset') restart();
  else if (a === 'endDayAsk') askEndDay();
  else if (a === 'rentIC') { hideModal(); const v = TAP_PEND && V(TAP_PEND.car); if (v) { v.rent = true; v.idle = false; v.dest = 'IC-INT'; toast(`${roadOf(v)} ${v.num} rented to IC: it goes on the next pickup.`, 'good'); save(); } TAP_PEND = null; }
  else if (a === 'bfReq') { bfRequest(b.dataset.k); bfPanel(b.dataset.k); }
  else if (a === 'bfOpen') bfPanel(b.dataset.k);
  else if (a === 'waybills') showWaybills();
  else if (a === 'wbCar') showWaybill(b.dataset.id, false);
  else if (a === 'tapGo') { hideModal(); if (TAP_PEND) { TAP_ASKED = true; sceneTap(TAP_PEND.sx, TAP_PEND.sy); } TAP_PEND = null; }
  else if (a === 'makeEngine') { hideModal(); claimEngine(b.dataset.id); }
  else if (a === 'callSheet') { if (window.NII_CALLSHEET) NII_CALLSHEET.open(); }
  else if (a === 'dayDone') { if (window.NII_CALLSHEET && NII_CALLSHEET.pendingTieUps()) NII_CALLSHEET.showTieUps(); else { hideModal(); state.help = false; save(); } }
  else if (a === 'endDay') { const r = endDay(); showDaySummary(r); (r.returned || []).forEach(t => toast(t + '.', 'good')); sfx(r.pay ? 'cash' : 'tick'); }
});
function askRestart() { showModal(NII_SHARED.RESTART_HTML + `<div class="btns"><button data-act="close" class="alt">Cancel</button><button data-act="reset" class="red">Yes, restart</button></div>`); }
