$('stopBtn').onclick = () => { if (state.ap) { state.ap.target = null; } state.ap = null; const c = locoCons(); state.mode === 'tap' && (state.stopping = true); toast('Stopping.'); }; // STOP eases off at NII_SHARED.STOP_DEC (simStep)
