const HOUSES = [['bungalow-a', 30, 40], ['bungalow-b', 32, 45], ['hipbungalow-a', 34, 45], ['foursquare-a', 34, 50], ['foursquare-b', 34, 50], ['ranch-a', 36, 50], ['cape-a', 32, 45], ['lcottage-a', 32, 40]];
